CREATE TEMP TABLE s_work_order_requirement (rpk bigint, created timestamptz, _item_item_pk bigint, allocated numeric, _work_order_work_order_pk bigint, "sequence" integer, operation integer, fixed_quantity numeric, quantity_per numeric, required numeric, _unit_item_unit_pk bigint, ratio numeric, reference text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, cwr.number || '.' || s.sequence, (b.b+s._item_item_pk), cwr._site_site_pk, CASE WHEN cwr.status = 'C' THEN 0 ELSE s.required END, cwr.start_date, cwr.status, s.allocated, '2', (b.b+s._work_order_work_order_pk), s."sequence", s.operation, s.fixed_quantity, s.quantity_per, s.required, CASE WHEN cwr.status = 'C' THEN s.required ELSE 0 END, 0, ROW(((cri.cost).amount * s.required),'USD',NULL,((cri.cost).amount * s.required))::mono, CASE WHEN cwr.status = 'C' THEN ROW(((cri.cost).amount * s.required),'USD',NULL,((cri.cost).amount * s.required))::mono END, (b.b+s._unit_item_unit_pk), s.ratio, false, s.reference FROM s_work_order_requirement s CROSS JOIN _fbbase b JOIN item cri ON cri._pk = b.b + s._item_item_pk JOIN ONLY work_order cwr ON cwr._pk = b.b + s._work_order_work_order_pk;

CREATE TEMP TABLE s_work_order_operation (rpk bigint, created timestamptz, "sequence" integer, run_time numeric, estimated_machine_hours numeric, estimated_labor_hours numeric, service_lead_time numeric, planned_start_time timestamptz, planned_end_time timestamptz, outside_process_id text, actual_service_cost numeric, capacity_time numeric, lead_time numeric, status text, "number" text, planned numeric, completed numeric, rejected numeric, remaining numeric, _work_order_work_order_pk bigint, on_hold boolean, setup_complete boolean, to_complete numeric, available numeric, is_last boolean, started numeric, is_manual_add boolean) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, s."sequence", cpo._machine_resource_machine_resource_pk, cpo._labor_resource_labor_resource_pk, cpo.queue_time, cpo.setup_time, cpo.run_rate, cpo.run_unit, s.run_time, cpo.wait_time, cpo.move_time, cpo."yield", cpo.machine_capacity, cpo.labor_capacity, cpo.transfer_batch_policy, coalesce(cmr.overhead_cost, ROW(0,'USD',NULL,0)::mono), coalesce(clr.labor_cost, ROW(0,'USD',NULL,0)::mono), ROW(round(coalesce((cmr.overhead_cost).amount,0)*s.capacity_time*cpo.machine_capacity,2),'USD',NULL,round(coalesce((cmr.overhead_cost).amount,0)*s.capacity_time*cpo.machine_capacity,2))::mono, ROW(round(coalesce((clr.labor_cost).amount,0)*s.capacity_time*cpo.labor_capacity,2),'USD',NULL,round(coalesce((clr.labor_cost).amount,0)*s.capacity_time*cpo.labor_capacity,2))::mono, coalesce(csv.service_cost, ROW(0,'USD',NULL,0)::mono), ROW(round(coalesce((csv.service_cost).amount,0)*s.planned,2),'USD',NULL,round(coalesce((csv.service_cost).amount,0)*s.planned,2))::mono, cpo._service_service_pk, s.estimated_machine_hours, s.estimated_labor_hours, s.service_lead_time, (s.planned_start_time + make_interval(days => b.shift)), (s.planned_end_time + make_interval(days => b.shift)), s.outside_process_id, ROW(s.actual_service_cost,'USD',NULL,s.actual_service_cost)::mono, cpo.batch_size, cpo.description, s.capacity_time, s.lead_time, s.status, s."number", s.planned, s.completed, s.rejected, s.remaining, (b.b+s._work_order_work_order_pk), CASE WHEN s.status = 'C' THEN ROW(round(coalesce((clr.labor_cost).amount,0)*s.capacity_time*cpo.labor_capacity,2),'USD',NULL,round(coalesce((clr.labor_cost).amount,0)*s.capacity_time*cpo.labor_capacity,2))::mono ELSE ROW(0,'USD',NULL,0)::mono END, CASE WHEN s.status = 'C' THEN ROW(round(coalesce((cmr.overhead_cost).amount,0)*s.capacity_time*cpo.machine_capacity,2),'USD',NULL,round(coalesce((cmr.overhead_cost).amount,0)*s.capacity_time*cpo.machine_capacity,2))::mono ELSE ROW(0,'USD',NULL,0)::mono END, s.on_hold, s.setup_complete, s.to_complete, s.available, s.is_last, s.started, s.is_manual_add FROM s_work_order_operation s CROSS JOIN _fbbase b JOIN work_order cwo ON cwo._pk = b.b + s._work_order_work_order_pk JOIN ONLY product_operation cpo ON cpo._product_product_pk = cwo._item_item_pk   AND cpo.sequence = s.sequence LEFT JOIN ONLY machine_resource cmr ON cmr._pk = cpo._machine_resource_machine_resource_pk LEFT JOIN ONLY labor_resource clr ON clr._pk = cpo._labor_resource_labor_resource_pk LEFT JOIN ONLY service csv ON csv._pk = cpo._service_service_pk;

