CREATE TEMP TABLE s_inventory_transaction (rpk bigint, created timestamptz, "number" text, "date" date, _item_item_pk bigint, quantity numeric, reference text, "type" text, document text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s."number", (s."date" + b.shift), (b.b+s._item_item_pk), (SELECT z._pk FROM ONLY site z LIMIT 1), s.quantity, '', coalesce(sum(s.quantity) OVER (PARTITION BY s._item_item_pk ORDER BY s.rpk ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0), sum(s.quantity) OVER (PARTITION BY s._item_item_pk ORDER BY s.rpk), ROW(((ci.material_cost).amount * s.quantity),'USD',NULL,((ci.material_cost).amount * s.quantity))::mono, ROW(((ci.labor_cost).amount * s.quantity),'USD',NULL,((ci.labor_cost).amount * s.quantity))::mono, ROW(((ci.service_cost).amount * s.quantity),'USD',NULL,((ci.service_cost).amount * s.quantity))::mono, ROW(((ci.overhead_cost).amount * s.quantity),'USD',NULL,((ci.overhead_cost).amount * s.quantity))::mono, ROW(((ci.cost).amount * s.quantity),'USD',NULL,((ci.cost).amount * s.quantity))::mono, s.reference, s."type", s.document FROM s_inventory_transaction s CROSS JOIN _fbbase b JOIN item ci ON ci._pk = b.b + s._item_item_pk;

CREATE TEMP TABLE s_inventory (rpk bigint, created timestamptz, "number" text, _item_item_pk bigint, _site_site_pk bigint, quantity numeric, start_date date, due_date date, status text, priority text, allocated numeric, notes text, material_value numeric, labor_value numeric, service_value numeric, overhead_value numeric, total_value numeric, available numeric, at_inspection numeric, blocked numeric, on_order numeric, demand numeric, shortage boolean, reorder boolean, projected numeric, _item_site_item_site_pk bigint, last_count date, is_active_count boolean) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s."number", (b.b+s._item_item_pk), (b.b+s._site_site_pk), s.quantity, (s.start_date + b.shift), (s.due_date + b.shift), s.status, s.priority, s.allocated, s.notes, ROW(s.material_value,'USD',NULL,s.material_value)::mono, ROW(s.labor_value,'USD',NULL,s.labor_value)::mono, ROW(s.service_value,'USD',NULL,s.service_value)::mono, ROW(s.overhead_value,'USD',NULL,s.overhead_value)::mono, ROW(s.total_value,'USD',NULL,s.total_value)::mono, s.available, s.at_inspection, s.blocked, s.on_order, s.demand, s.shortage, s.reorder, s.projected, (b.b+s._item_site_item_site_pk), (s.last_count + b.shift), s.is_active_count FROM s_inventory s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_allocation (rpk bigint, created timestamptz, _demand_demand_pk bigint, _supply_supply_pk bigint, quantity numeric, is_firm boolean, _sales_demand_demand_pk bigint, _sales_order_sales_order_pk bigint) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), (b.b+s._demand_demand_pk), (b.b+s._supply_supply_pk), s.quantity, s.is_firm, (b.b+s._sales_demand_demand_pk), (b.b+s._sales_order_sales_order_pk) FROM s_allocation s CROSS JOIN _fbbase b;

-- document number sequences continue past the loaded data
DO $seq$
BEGIN
    IF to_regclass('public.sales_seq') IS NOT NULL THEN PERFORM setval('public.sales_seq', 2141, false); END IF;
    IF to_regclass('public.work_order_seq') IS NOT NULL THEN PERFORM setval('public.work_order_seq', 1834, false); END IF;
    IF to_regclass('public.purchase_seq') IS NOT NULL THEN PERFORM setval('public.purchase_seq', 27034, false); END IF;
    IF to_regclass('public.receipt_seq') IS NOT NULL THEN PERFORM setval('public.receipt_seq', 7740, false); END IF;
    IF to_regclass('public.shipment_seq') IS NOT NULL THEN PERFORM setval('public.shipment_seq', 956, false); END IF;
    IF to_regclass('public.invoice_seq') IS NOT NULL THEN PERFORM setval('public.invoice_seq', 956, false); END IF;
    IF to_regclass('public.inv_trans_seq') IS NOT NULL THEN PERFORM setval('public.inv_trans_seq', 109248, false); END IF;
    IF to_regclass('public.inventory_adjust') IS NOT NULL THEN PERFORM setval('public.inventory_adjust', 68, false); END IF;
END
$seq$;

DO $check$
DECLARE v_bad bigint; v_neg bigint;
BEGIN
    SELECT count(*) INTO v_bad FROM (
        SELECT i._item_item_pk FROM ONLY public.inventory i
        LEFT JOIN (SELECT _item_item_pk, sum(quantity) q FROM ONLY public.inventory_transaction GROUP BY 1) t
          ON t._item_item_pk = i._item_item_pk
        WHERE round(coalesce(t.q,0),6) <> round(i.quantity,6)) z;
    IF v_bad > 0 THEN
        RAISE EXCEPTION 'Inventory does not equal the sum of its transactions for % item(s). Rolling back.', v_bad;
    END IF;
    SELECT count(*) INTO v_neg FROM ONLY public.inventory_transaction WHERE quantity_after < 0;
    IF v_neg > 0 THEN
        RAISE EXCEPTION '% transaction(s) leave a negative balance. Rolling back.', v_neg;
    END IF;
    RAISE NOTICE 'Teardrop Campers demo data loaded: 271109 rows.';
END
$check$;

COMMIT;

ANALYZE;
